#!/usr/bin/env bash
# build.sh - build service_demo with lazbuild (Linux / macOS / MSYS2)
# generated by the lazarusWeb project wizard. First time:
#   chmod +x build.sh && ./build.sh
set -eu
cd "$(dirname "$0")"
LAZBUILD="${LAZBUILD:-lazbuild}"
command -v "$LAZBUILD" >/dev/null 2>&1 || {
  for c in /usr/bin/lazbuild /usr/local/bin/lazbuild /opt/lazarus/lazbuild \
           "$HOME/lazarus/lazbuild" \
           /Applications/Lazarus/lazbuild.app/Contents/MacOS/lazbuild; do
    [ -x "$c" ] && LAZBUILD="$c" && break
  done
}
command -v "$LAZBUILD" >/dev/null 2>&1 || [ -x "$LAZBUILD" ] || {
  echo "lazbuild not found. Install Lazarus or: export LAZBUILD=/path/to/lazbuild" >&2
  exit 1
}
"$LAZBUILD" -B service_demo.lpi "$@"
echo
echo "  run:  ./service_demo --port=8090"
echo "  open: http://127.0.0.1:8090/"
